uniform float density : 0.0 .. 1.0 = 0.05;
uniform float speed : 0.0 .. 5.0 = 1.0;
uniform vec3 color : color = 1.0, 0.9, 0.6;
state fixed phase;
void update() {
  phase = fract(phase + fixed(dt * speed));
}
vec3 shade(Led led) {
  fixed s = fixed(led.s);
  fixed h = hash(s * fixed(1000.0) + phase);
  fixed t = hash(s * fixed(2000.0) + phase + fixed(0.5));
  fixed on = step(fixed(1.0) - fixed(density), h);
  fixed blink = step(fixed(0.5), t);
  fixed v = on * blink;
  return color * float(v);
}
